add('05_001','春子向右侧脸近景，持刀手和柄在右上，另一只手在右下环腕。',['春子','持刀手','抓腕手','刀柄'],[],['眼皮半垂','内眉高外眉低','抓腕持续'],'灰色渐变底面',[['好吧','春子','……分かった。']],'Reaction，腕仍受抓握，顺气接受暂停，源側脸为尾段。',['春子向右凝视',['缓缓呼气','下颌微退、唇闭合'],'让步体现在握持减压，接触未断','目光仍向右，腕停着'],'短让步不突然回正或笑；与前插入手镜直接接续，腕上的手仍在。',3,['85mm平视春子向右侧脸近景，持刀手和柄在右上，抓腕的手在右下边缘；固定机位，脸与两手接触同框。','春子朝右凝视，缓缓呼出一口气，下颌微微退后。她短短说完，嘴唇闭合，半垂眼形和高挑内眉仍在；握柄的手松去一点绷劲，腕侧的另一只手持续接触。','背景为低亮深灰蓝水面，弧形冷白远光沿侧脸后方铺开。','春子说：“……分かった。”（偏低女声，短停后勉强答应，音量稍降，近距离。）','冷白侧光轻亮鼻尖和指背，棕色刘海下保持深影，柄缠布有柔和灰白层。','一口缓慢呼气，衣袖轻擦，低柔水声持续。'])
add('05_002','一只浅色手握住兜帽顶边，深色袍面横占下部。',['春子的手','兜帽'],['手抓住兜帽布边'],['抓点在上中央'],'灰白简化底面',[['那你看了这个混蛋的脸再做判断吧.','春子','じゃあ、こいつの顔を見てから判断して。']],'Action，已换至抓帽任务；手先贴顶边抓紧，源握边为中段，再沿上方掀起最短行程。',['手贴近兜帽顶边',['指尖圈住布边','布边受力提起一点'],'让青看脸，实际只演抓帽掀边','帽边受力上抬，脸仍在布内'],'同场动作任务从握刀切到抓帽；两手关系变化未在源图说明，以物件新任务切入，不虚构换手和收刀过程。',7,['85mm平视抓帽局部近景，浅色手由上左伸到中央，兜帽尖边在手下，灰黑布面延展到右下；固定机位，抓点居中。','手掌贴住兜帽上沿，指尖圈紧布边。布面在抓点收出短褶，手沿上方提起一小段，帽缘随力道抬高，较宽的黑袍仍压在下方；抓紧的布边继续上移。','背景是低亮深灰蓝水面远层，上方留白冷静，水光仅有浅灰亮带。','春子画外说：“じゃあ、こいつの顔を見てから判断して。”（偏低女声，语气直接而带不耐，把判断交回对方，自然语速。）','冷白柔光落在指背和灰黑布褶上，抓点阴影加深，布面有清晰厚度。','指尖抓布一声轻擦，袍料受力窸窣，水声连续。'],flags=['G'])
